-- Migration 0038_matter_documents: generated by drizzle-kit (tables, keys, indexes), RLS, the column-list SET NULL actions and the orphan cleanup hand-written, reviewed before commit.
-- Reviewed-by: Claude (agent, #345)
-- Matter and documents (#345, part 2 of #32; ADR 0013):
--   * matter, document, document_page, anchor: tenant tables (tenantTable()) under FORCE RLS with
--     ws_isolation (tenantPolicy()). Every child FK is composite (workspace_id, <parent>_id) ->
--     parent(workspace_id, id); matter, document and anchor carry the unique (workspace_id, id) the
--     FKs target (anchor for the provenance anchor_id FKs of #346-#348). Grants come from the
--     default privileges (app: 02-roles.sql, clerk: 0022).
--   * The nullable composite FKs whose parent can go away (matter.owner_member_id: account deletion
--     cascades member; matter.merged_into_matter_id and document.supersedes_document_id: the erase
--     deletes in 500-row batches) are ON DELETE SET NULL (<column>) (Postgres 15+). drizzle-kit
--     writes a plain SET NULL, which would also null the NOT NULL workspace_id; its snapshot keeps
--     `set null`.
--   * matter_restriction.matter_id gets its FK to matter (composite, ON DELETE CASCADE), left out by
--     0022 until matter existed. matter is created empty here, so every existing restriction names a
--     matter that can never exist: they are deleted first. FORCE RLS binds the owner running this
--     migration, so it is lifted for that statement only (as in 0027).
-- Expand only: new tables; matter_restriction loses its orphan rows and gains a constraint.
CREATE TABLE "anchor" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"document_id" uuid NOT NULL,
	"page_no" integer NOT NULL,
	"quote" text NOT NULL,
	"char_start" integer,
	"char_end" integer,
	"bbox" jsonb,
	"kind" text NOT NULL,
	"transcript_span" jsonb,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	"workspace_id" uuid NOT NULL,
	CONSTRAINT "anchor_workspace_id_id_uq" UNIQUE("workspace_id","id"),
	CONSTRAINT "anchor_kind_chk" CHECK (kind in ('document', 'transcript', 'list_row', 'calendar_event', 'email', 'image_region')),
	CONSTRAINT "anchor_quote_length_chk" CHECK (char_length(quote) <= 2000),
	CONSTRAINT "anchor_page_no_chk" CHECK (page_no >= 1),
	CONSTRAINT "anchor_char_range_chk" CHECK ((char_start is null or char_start >= 0) and (char_end is null or char_start is null or char_end >= char_start))
);
--> statement-breakpoint
