	"text_status" "document_text_status" DEFAULT 'pending' NOT NULL,
	"source_capture_id" uuid,
	"matter_id" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	"workspace_id" uuid NOT NULL,
	CONSTRAINT "document_workspace_id_id_uq" UNIQUE("workspace_id","id"),
	CONSTRAINT "document_sha256_chk" CHECK (sha256 ~ '^[0-9a-f]{64}$'),
